                    break
        elif isinstance(anchor, RE_TYPE):
            link = None
            for l in (context or self.doc).cssselect('a'):
                if re.search(anchor, get_all_text(l)):
                    link = l
                    break
        elif isinstance(anchor, lxml.etree._Element):
